const http = require('http');
const WebSocket = require('ws');
const jwt = require('jsonwebtoken');
const { MongoClient } = require('mongodb');

const server = http.createServer();
const wss = new WebSocket.Server({ server });
let mongoDb;

MongoClient.connect(process.env.MONGO_URI).then(client => {
  mongoDb = client.db('hospital_telemetry');
});

wss.on('connection', (ws, req) => {
  const token = req.headers['sec-websocket-protocol'];
  try {
    ws.practitioner = jwt.verify(token, process.env.JWT_SECRET);
  } catch (err) {
    ws.close(1008, 'Invalid token');
    return;
  }

  ws.on('message', async (msg) => {
    const { command, mrn } = JSON.parse(msg);

    if (command === 'STREAM_VITALS') {
      // Verify clinician is on the patient's active care team
      const assignment = await mongoDb.collection('care_assignments').findOne({
        medicalRecordNumber: mrn,
        practitionerId: ws.practitioner.staffId,
        isActive: true
      });

      if (!assignment) {
        ws.send(JSON.stringify({ error: 'Access denied: not assigned to this patient' }));
        return;
      }

      const changeStream = mongoDb.collection('patient_vitals').watch([
        { $match: { 'fullDocument.medicalRecordNumber': mrn } }
      ]);

      changeStream.on('change', (change) => {
        ws.send(JSON.stringify(change.fullDocument));
      });

      ws.on('close', () => changeStream.close());
    }
  });
});

server.listen(8004);
